from pathlib import Path
import json,itertools,math
D=Path('runtime/customer-readiness-20261015');s=json.loads((D/'r8-geometry-topology.json').read_text(encoding='utf-8'));roof=next(g for g in s['groups'] if g['name']=='ROOF_TIMBER')['children'][1];posts=[g for g in roof['children'] if g['name'].startswith('TIMBER_POST_')];env=next(g for g in s['groups'] if g['name']=='ENVELOPE_OUTER');ties=next(g for g in env['children'] if g['name']=='TENSION_BRACING');ext=next(g for g in s['groups'] if g['name']=='CIRCULATION_EXTERNAL');galleries=next(g for g in ext['children'] if g['name']=='GALLERIES');decks=[g for g in galleries['children'] if g['name'] in ['GALLERY_Z3600_SIDE0','GALLERY_Z3600_SIDE1']]
def exact_box(g):
 v=g['vertices_world_mm'];bounds=[[min(p[k] for p in v),max(p[k] for p in v)] for k in range(3)];corners={tuple(round(q,3) for q in p) for p in itertools.product(*bounds)};actual={tuple(round(q,3) for q in p) for p in v};assert len(g['faces'])==6 and actual==corners,(g['name'],len(g['faces']),len(actual));return bounds
def inside(p,b,tol=.01):return all(b[k][0]-tol<=p[k]<=b[k][1]+tol for k in range(3))
